import sys
from collections import defaultdict, deque

def bfs(capacity, source, sink):
    queue = deque([source])
    parent = {node: None for node in capacity}
    parent[source] = source

    while queue:
        u = queue.popleft()
        for v in capacity[u]:
            if parent[v] is None and capacity[u][v] > 0:
                parent[v] = u
                if v == sink:
                    return parent
                queue.append(v)

    return None

def edmonds_karp(capacity, source, sink):
    max_flow = 0
    while True:
        path = bfs(capacity, source, sink)
        if path is None:
            break

        flow = float('Inf')
        s = sink
        while s != source:
            u = path[s]
            flow = min(flow, capacity[u][s])
            s = u

        v = sink
        while v != source:
            u = path[v]
            capacity[u][v] -= flow
            capacity[v][u] += flow
            v = u

        max_flow += flow

    return max_flow

def max_calm_group_sum(n, a, b):
    source = 0
    sink = n + 1
    capacity = defaultdict(lambda: defaultdict(int))

    for i in range(1, n + 1):
        capacity[source][i] = 1
        capacity[i][sink] = 1

    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if (a[i - 1] & a[j - 1]) == a[i - 1] or (a[i - 1] & a[j - 1]) == a[j - 1]:
                capacity[i][j] = 1
                capacity[j][i] = 1

    max_flow = edmonds_karp(capacity, source, sink)

    if max_flow < 2:
        return 0

    total_skill = 0
    for i in range(1, n + 1):
        if capacity[source][i] == 0:
            total_skill += b[i - 1]

    return total_skill

